const fs = require('node:fs');
const vm = require('node:vm');
const assert = require('node:assert/strict');
const html = fs.readFileSync('/workspace/firefly-garden.html', 'utf8');
const script = html.match(/<script>([\s\S]*?)<\/script>/)[1];
new vm.Script(script);

function environment(reduce = false, supported = true) {
  const callbacks = new Map();
  let nextId = 0;
  let dimensions = { width: 1000, height: 800, left: 0, top: 0 };
  const drawing = { arcs: [] };
  const ctx = new Proxy({}, {
    get(_, key) {
      if (key === 'clearRect') return () => { drawing.arcs = []; };
      if (key === 'arc') return (x, y, r) => {
        assert.ok([x, y, r].every(Number.isFinite), 'finite drawing coordinates');
        drawing.arcs.push({ x, y, r });
      };
      if (String(key).startsWith('create')) return () => ({ addColorStop() {} });
      return () => {};
    },
    set() { return true; }
  });
  function target() {
    const events = new Map();
    return {
      textContent: '', attributes: {},
      addEventListener(name, fn) { events.set(name, fn); },
      emit(name, value = {}) { events.get(name)?.(value); },
      setAttribute(name, value) { this.attributes[name] = value; }
    };
  }
  const canvas = Object.assign(target(), {
    getContext: () => supported ? ctx : null,
    getBoundingClientRect: () => dimensions
  });
  const elements = Object.fromEntries(['add', 'pause', 'hint', 'status'].map(id => [id, target()]));
  elements.garden = canvas;
  const media = Object.assign(target(), { matches: reduce });
  const document = Object.assign(target(), {
    hidden: false,
    getElementById: id => elements[id],
    createElement: () => ({ getContext: () => supported ? ctx : null })
  });
  const window = Object.assign(target(), { devicePixelRatio: 3, matchMedia: () => media });
  vm.runInNewContext(script, {
    document, window,
    requestAnimationFrame(fn) { const id = ++nextId; callbacks.set(id, fn); return id; },
    cancelAnimationFrame(id) { callbacks.delete(id); }
  });
  return {
    elements, canvas, document, window, media, drawing, callbacks,
    frame(t) {
      const pending = [...callbacks.values()];
      callbacks.clear();
      for (const fn of pending) fn(t);
    },
    resize(width, height) { dimensions = { ...dimensions, width, height }; window.emit('resize'); }
  };
}

const e = environment();
assert.equal(e.drawing.arcs.length, 26);
assert.equal(e.callbacks.size, 1);
assert.equal(e.canvas.width, 2000, 'device pixel ratio capped at two');
for (let i = 0; i < 120; i++) e.frame(i * 16.67);
assert.equal(e.drawing.arcs.length, 26);
assert.equal(e.callbacks.size, 1);
e.elements.pause.emit('click');
assert.equal(e.callbacks.size, 0);
assert.equal(e.elements.pause.attributes['aria-pressed'], 'true');
e.canvas.emit('click', { clientX: 400, clientY: 300 });
assert.equal(e.drawing.arcs.length, 27);
assert.deepEqual(e.drawing.arcs.at(-1), { x: 400, y: 300, r: e.drawing.arcs.at(-1).r });
assert.match(e.elements.status.textContent, /27 fireflies/);
e.resize(500, 400);
assert.equal(e.drawing.arcs.at(-1).x, 200);
assert.equal(e.drawing.arcs.at(-1).y, 150);
for (let i = 0; i < 100; i++) e.elements.add.emit('click');
assert.equal(e.drawing.arcs.length, 90, 'population remains bounded');
e.elements.pause.emit('click');
assert.equal(e.callbacks.size, 1);
e.document.hidden = true;
e.document.emit('visibilitychange');
assert.equal(e.callbacks.size, 0);
e.document.hidden = false;
e.document.emit('visibilitychange');
assert.equal(e.callbacks.size, 1);
e.media.emit('change', { matches: true });
assert.equal(e.callbacks.size, 0);
const reduced = environment(true);
assert.equal(reduced.callbacks.size, 0);
assert.equal(reduced.drawing.arcs.length, 26);
reduced.elements.add.emit('click');
assert.equal(reduced.drawing.arcs.length, 27);
const unsupported = environment(false, false);
assert.equal(unsupported.elements.add.disabled, true);
assert.equal(unsupported.elements.pause.disabled, true);
assert.equal(unsupported.callbacks.size, 0);
assert.ok(!/<(?:script|link)[^>]+(?:src|href)=/i.test(html), 'no external dependencies');
console.log('PASS: JavaScript syntax, initial scene, animation, pause/resume, pointer planting, live announcement, resize scaling, population cap, background suspension, reduced motion, canvas fallback, and no external dependencies.');
console.log('Behavior tested with mocked DOM/canvas; browser rendering was not tested (no browser installed).');
NODE
